# Minimal Multi-Agent Supervisor Pattern (pseudocode)
from typing import TypedDict, Literal

class AgentState(TypedDict):
    task: str
    research: str
    draft: str
    review_count: int
    is_approved: bool

def supervisor(state: AgentState) -> Literal["researcher", "writer", "critic", "finish"]:
    if not state.get("research"):
        return "researcher"
    if not state.get("draft"):
        return "writer"
    if not state.get("is_approved") and state.get("review_count", 0) < 3:
        return "critic"
    return "finish"
